 "content": "def transform(grid):
    """Align each colored shape's top with the top of the color-8 anchor."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    rows_by_color = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                rows_by_color.setdefault(color, []).append((r, c))
    if not rows_by_color:
        return [row[:] for row in grid]
    target_top = min(r for r, _ in rows_by_color[8]) if 8 in rows_by_color else min(r for cells in rows_by_color.values() for r, _ in cells)
    out = [[0] * w for _ in range(h)]
    for color, cells in rows_by_color.items():
        top = min(r for r, _ in cells)
        shift = target_top - top
        for r, c in cells:
            nr = r + shift
            if 0 <= nr < h:
                out[nr][c] = color
    return out
